    while (t && !t.data.length) { t = walk.nextNode(); }
    if (!t || t.data.charAt(0) !== '\n') { return; }
    t.data = t.data.slice(1);
    const back = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
