        if (r0 < 0) { return; }
        const isNum = (x) => x && x !== cell && (cellFormula(x) || typeof window.EditBaseCalc.literal(String(x.textContent || '')) === 'number');
        let top = r0;
        while (top > 0 && isNum(grid[top - 1][c0])) { top--; }
